css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 7px 12px; margin-bottom: 10px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 4px;}
.mz .recuerda-idea{font-size: 13.5px; margin-bottom: 3px; line-height: 1.38;}
.mz .recuerda-idea b{font-weight: 700;}
.mz .rec-eq{font-family: sans-serif; font-weight: 800; font-size: 15px;}
.mz .caja{width: 44px; height: 28px; border: 1.6px solid var(--bosque); border-radius: 6px; display: inline-block; vertical-align: middle;}
.mz .caja-sm{width: 40px; height: 26px;}
.mz .unidad-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 7px 22px;}
.mz .unidad-item{display: flex; align-items: center; justify-content: space-between; border: 1.5px solid var(--bosque); border-radius: 8px; padding: 5px 10px; gap: 8px;}
.mz .unidad-obj{font-size: 13.5px; font-weight: 700;}
.mz .unidad-ops{display: flex; gap: 7px; font-family: sans-serif;}
.mz .pill{border: 1.5px solid var(--bosque); border-radius: 999px; padding: 2px 9px; font-size: 11px; font-weight: 700; font-family: sans-serif; white-space: nowrap;}
.mz .vaso-grid{display: flex; justify-content: space-around; align-items: flex-end; gap: 10px; padding: 4px 18px;}
.mz .vaso-item{text-align: center;}
.mz .vaso-resp{display: flex; gap: 16px; justify-content: center; margin-top: 8px; font-family: sans-serif; font-weight: 700; font-size: 14px;}
.mz .vaso-resp .caja-sm{width: 34px; height: 24px;}
.mz .problema{border: 1.6px solid var(--bosque); border-radius: 9px; padding: 7px 11px; margin-bottom: 8px; font-size: 13.5px; line-height: 1.35;}
.mz .op-line{display: flex; align-items: center; gap: 8px; margin-top: 6px; font-family: sans-serif; font-weight: 700; font-size: 13px; flex-wrap: wrap;}
.mz .op-line .sol{flex: 1; min-width: 120px; border-bottom: 1.4px solid var(--bosque); height: 16px;}
.mz .problema,.mz .recuerda-idea{line-height: 1.725 !important;}
